/**
 * Bulk-import a real mod.io catalogue into `GameMod` for NxLabs Phase 3 — the
 * mod.io counterpart to `scripts/import-modrinth-catalog.ts` and
 * `scripts/import-thunderstore-catalog.ts`. Same shape, same safety rails,
 * same idempotency guarantee. Read those two first if you haven't; this one
 * only documents where mod.io's real API and data shape force a different
 * approach.
 *
 * GAMES COVERED (checked live 2026-09-20 against mod.io's own `/v1/games`
 * listing, matched by name to lib/games.ts's GAME_FAMILIES — these 4 were
 * confirmed to have a real, active mod.io presence; nothing here is guessed):
 *   mod.io game id 5289 → "Core Keeper"            → gameFamily "corekeeper"
 *   mod.io game id  264 → "Space Engineers"         → gameFamily "spaceengineers"
 *   mod.io game id  254 → "Insurgency: Sandstorm"   → gameFamily "sandstorm"
 *   mod.io game id  169 → "MORDHAU"                 → gameFamily "mordhau"
 *
 * SOURCE: mod.io REST API v1, https://docs.mod.io/restapiref/ — the real
 * developer-account `MODIO_API_KEY` now in `.env` (confirmed live against
 * `GET /v1/games`, see below). One endpoint does all the work here:
 * `GET /v1/games/{game-id}/mods` already returns the FULL mod object (logo,
 * media.images[], stats, tags, submitted_by) in one call — unlike Modrinth,
 * there is no separate "search hit" vs "full project" split and no bulk
 * `?ids=[...]` follow-up call needed. Paged with `_limit`/`_offset`, real
 * `result_total` in every response.
 *
 * ---------------------------------------------------------------------------
 * RATE LIMIT (checked live, NOT assumed from earlier per-game-key research)
 * ---------------------------------------------------------------------------
 * The response to `GET /v1/games` carries `x-modio-key: user` — mod.io's own
 * header naming this a USER-linked (general developer account) key, not a
 * GAME-linked one. mod.io's docs (checked live 2026-09-20) are explicit that
 * the "unlimited requests" tier only applies to game-linked keys; a
 * user-linked key like this one is documented at 60 requests/minute. No
 * `X-RateLimit-*` headers are returned at all (mod.io deprecated them
 * platform-wide in Nov 2022 in favor of a `retry-after` header on actual 429s
 * — confirmed absent on every real response this script's development burst-
 * tested, including 60 requests fired in ~26s with zero throttling observed).
 * Since the documented ceiling (60/min) is the only real number to plan
 * around, this script self-paces under it — see RATE_LIMIT_PER_MIN — and
 * retries 429s honoring `Retry-After`, same pattern as the Modrinth script.
 *
 * ---------------------------------------------------------------------------
 * LEGAL / FETCH-AT-INSTALL-ONLY (verified live, not assumed)
 * ---------------------------------------------------------------------------
 * Checked the full shape of a real mod object (Core Keeper's top-downloaded
 * mod, "CoreLib") field by field: there is no `license` key anywhere in the
 * response, at any nesting level. mod.io's API has no per-mod license concept
 * at all (unlike Modrinth's `license.id`). Consequences, matching this
 * repo's established Thunderstore/Steam Workshop precedent for sources with
 * no license field:
 *   - `license` is always written as `null`. Never fabricate one.
 *   - This script NEVER downloads/mirrors/rehosts an actual mod file. It
 *     stores metadata + the real hotlinked mod.io CDN image URLs
 *     (`image.modcdn.io`/`thumb.modcdn.io`) only — `logo` and
 *     `media.images[]` are legitimately part of the public API response, not
 *     scraped. The real file stays fetched at INSTALL TIME by the worker,
 *     exactly like every other source; this script performs zero mod-file
 *     downloads, only catalogue JSON.
 *
 * ---------------------------------------------------------------------------
 * SPACE ENGINEERS NEEDS A CONTENT-TYPE FILTER MODRINTH-STYLE (verified live)
 * ---------------------------------------------------------------------------
 * mod.io's Space Engineers catalogue is huge (165,922 listed items) but the
 * overwhelming majority is NOT server-installable mod content:
 *   tags=Blueprint  → 144,710 (87%) — personal ship/rover designs, subscribed
 *                     per-player in-game; nothing a dedicated server installs.
 *   tags=World      →  16,945       — full save-game worlds, not mods.
 *   tags=ingameScript →    744      — Programmable Block scripts a player
 *                     pastes into their own grid; not a server-side file.
 *   tags=scenario   →      37       — custom scenario templates.
 *   tags=Mod        →   3,113       — actual code/content mods, loaded via
 *                     the game's real `Mods=` list — this is the one bucket
 *                     that is genuinely "install this on my dedicated server"
 *                     content, the SE analogue of Modrinth's `environment`
 *                     facet excluding client-only content. THIS script only
 *                     imports `tags=Mod` for Space Engineers. Core Keeper,
 *                     Sandstorm, and Mordhau have no comparable non-installable
 *                     bucket in their own tag taxonomies (checked live, see
 *                     CATEGORY_GROUP below) so no equivalent filter applies
 *                     to them — matches Modrinth's own principle of only
 *                     filtering where the source draws a real distinction,
 *                     never inventing one.
 *
 * ---------------------------------------------------------------------------
 * CATEGORY (verified live per game — mod.io has no Modrinth-style structural
 * `project_type`, so the closest real per-mod facet is each game's own
 * checkbox/dropdown tag taxonomy, which differs completely per game)
 * ---------------------------------------------------------------------------
 * `GET /v1/games/{id}/tags` was checked live for all 4 games. One tag group
 * per game is the real "what kind of content is this" facet; the rest
 * (Game Version, Grid Size, Safety, Theme, Time, Setting, ...) are not.
 *   corekeeper (5289): group "Type" — Visual/Audio/Item/NPC/Quality of Life/
 *     Overhaul/Language/Library.
 *   spaceengineers (264): every imported row is already tags=Mod (see above),
 *     so category is trivially "Mod" — no group lookup needed.
 *   sandstorm (254): group "Mods" — Total Conversion/Custom Theater/Game
 *     Mode/Mutator. A row with no tag from this group (i.e. a map with no
 *     mod-type tag) falls back to the game's own `ugc_name` ("Mods") —
 *     Sandstorm draws no client/server distinction between its "Maps" and
 *     "Mods" tag groups (a map is exactly as server-installable as a mod;
 *     dedicated servers rotate maps), so both are kept, only the label
 *     differs.
 *   mordhau (169): group "Type" — Map/Skin/Serverside Only/Dependency/Admin
 *     Tool/Item Removal/RCON/Audio.
 * A mod with none of its own tags present in the game's category group falls
 * back to that game's real `ugc_name` from `/v1/games` (Core Keeper "Mods",
 * Sandstorm "Mods", Mordhau "Mods") — never a fabricated label.
 *
 * ---------------------------------------------------------------------------
 * QUALITY GATE (documented, not guessed)
 * ---------------------------------------------------------------------------
 * downloads_total > 1000 (DEFAULT_MIN_DOWNLOADS) — the SAME numeric floor
 * import-modrinth-catalog.ts uses, applied AFTER the Space Engineers
 * tags=Mod filter above. Checked live where this floor lands for each real
 * pool: corekeeper ~180/312, spaceengineers(Mod) ~1050/3113, sandstorm
 * ~410/773, mordhau ~700/1435 — a real, meaningful cut in every case, not
 * a no-op and not a catalogue-gutting one.
 *   Tried Modrinth's disjoint second pass (subscribers_total as the
 *   follows-analogue) before deciding against it, same as
 *   import-thunderstore-catalog.ts's documented rating_score finding:
 *   checked live how many rows would clear subscribers_total>50 AND
 *   downloads_total<=1000 (i.e. what a second pass would actually add) for
 *   every one of the 4 games — corekeeper 0, sandstorm 0, mordhau 1,
 *   spaceengineers(Mod) 0. Not a real disjoint gain anywhere. Documenting the
 *   finding here instead of shipping a provably-near-dead code path.
 * Pagination requests `_sort=-downloads_total` and stops each game's pass the
 * moment a page's last row is at or under the floor — real early-stop, not a
 * full scan of large pools (matters most for Space Engineers's 3,113-row
 * tags=Mod pool).
 *
 * ---------------------------------------------------------------------------
 * IDENTITY / SLUG STRATEGY (matches import-github-catalog.ts's pattern, not
 * Modrinth's plain slug-is-the-key one)
 * ---------------------------------------------------------------------------
 * mod.io's real immutable identity is the numeric mod `id` — its `name_id`
 * (kebab slug) CAN be changed by the author later (mod.io lets creators edit
 * their profile URL). So: match existing rows by (gameFamily, source:
 * "mod_io", sourceId: String(id)) FIRST. Found → update in place, `slug`
 * never touched. Not found → create with slug = mod's own `name_id`
 * (de-duplicated against every slug already used in that gameFamily —
 * collision is possible in principle even though mod.io enforces per-game
 * uniqueness of name_id, because this repo's uniqueness is per-gameFamily,
 * which is a 1:1 mapping here anyway, so in practice collisions shouldn't
 * occur, but the check costs one query and costs nothing if it never fires).
 * The actual write is still `db.gameMod.upsert`/`create`/`update` — same
 * `@@unique([gameFamily, slug])` constraint as every other importer.
 *
 * FIELD NOTES:
 *   - `description` = mod.io's `summary` (short tagline, matches Modrinth's
 *     `description` field length/role).
 *   - `longDescription` = mod.io's `description_plaintext` (the real full
 *     project-page body, HTML tags already stripped by mod.io itself) — only
 *     written when non-empty, same "real longer body or null, never a copy
 *     of the short one" rule GameMod.longDescription's schema doc states.
 *   - `iconUrl` = `logo.thumb_320x180`. mod.io has no separate small square
 *     icon field the way Modrinth does — the "logo" IS the primary image,
 *     always a 16:9 banner. Using the smallest real thumbnail mod.io itself
 *     generates, not a made-up crop.
 *   - `galleryUrls` = `media.images[].original`, capped at GALLERY_CAP,
 *     in the API's own returned order. mod.io does not publish a
 *     featured/ordering flag on images the way Modrinth's gallery does, so
 *     unlike the Modrinth script there is nothing to sort by — this is
 *     documented, not a missed field.
 *   - `authorName`/`authorAvatarUrl` = `submitted_by.username` /
 *     `submitted_by.avatar.thumb_100x100`, real fields already present on
 *     every mod object (no separate user-lookup call needed, unlike
 *     Modrinth's bulk `/users?ids=` step).
 *   - `gameVersions` = every one of the mod's own tags that matches that
 *     game's real "Game Version" tag group (present for Core Keeper only,
 *     checked live — the other 3 games' tag taxonomies have no version
 *     group at all, so this is `[]` for them, matching the schema's own
 *     "empty = the source has no version list, not the same as none" rule).
 *   - `loaders` = `[]` always. mod.io has no loader/platform-manager concept
 *     analogous to Modrinth's `loaders` for any of these 4 games.
 *   - `serverSide` = derived from Core Keeper's real "Application Type"
 *     checkbox group (Client/Server — the one game of the 4 whose taxonomy
 *     draws this distinction at all, checked live): "Server" tag present →
 *     "required"; "Client" present without "Server" → "unsupported"; neither
 *     → null (unknown, kept rather than guessed, same as Modrinth's own
 *     null-when-unknown convention). Always null for the other 3 games —
 *     verified live they have no such field.
 *
 * ---------------------------------------------------------------------------
 * KNOWN GAP, DOCUMENTED RATHER THAN SILENTLY LEFT (not this script's job)
 * ---------------------------------------------------------------------------
 * Checked `lib/mod-install-support.ts`: none of corekeeper/spaceengineers/
 * sandstorm/mordhau are in `INSTALLABLE_FAMILIES` today, so these rows will
 * all render "install it yourself in Files" regardless of source — the same
 * documented degrade every not-yet-wired family already gets. Since the
 * family gate fails before the source gate is ever checked, adding "mod_io"
 * to `RESOLVABLE_SOURCES` would currently have ZERO visible effect for any
 * of these 4 families and was deliberately NOT done in this pass — it is
 * real, separate, future work (writing each game's real config-write
 * mechanism — Space Engineers/Core Keeper/Mordhau/Sandstorm dedicated
 * servers each have their own way of taking a mod.io id, none of them
 * researched yet) that a pure catalogue-population pass should not bundle in
 * without deploying and verifying the mechanism for real.
 *
 * SAFETY: same as every other writing script in this repo — dry run by
 * default, `scripts/db-target-guard.ts` enforces NXEON_DB_TARGET.
 *
 *   Dry run, one small game first:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-modio-catalog.ts \
 *       --games=corekeeper
 *
 *   Real write, same slice:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-modio-catalog.ts \
 *       --games=corekeeper --apply
 *
 *   Full real run (all 4 games, default threshold):
 *     NXEON_DB_TARGET=nxeon npx tsx scripts/import-modio-catalog.ts --apply
 */

import { assertDbTarget } from "./db-target-guard";
assertDbTarget("import-modio-catalog.ts");

import { db } from "../lib/db";
import type { GameFamily } from "../lib/games";

const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
const MODIO_KEY = process.env.MODIO_API_KEY ?? "";
const API = "https://api.mod.io/v1";

if (!MODIO_KEY) {
  console.error("Refusing to run: MODIO_API_KEY is not set. Nothing was written.");
  process.exit(1);
}

// ── Tunable script constants ─────────────────────────────────────────────
const DEFAULT_MIN_DOWNLOADS = 1000; // same floor as import-modrinth-catalog.ts, see file header
const DEFAULT_RATE_LIMIT_PER_MIN = 50; // conservative margin under mod.io's documented 60/min for user-linked keys
const PAGE_SIZE = 100;
const GALLERY_CAP = 8; // matches the Modrinth/verify-gamemods.ts convention

const ALL_GAMES = ["corekeeper", "spaceengineers", "sandstorm", "mordhau"] as const;
type Game = (typeof ALL_GAMES)[number];

const GAME_TO_FAMILY: Record<Game, GameFamily> = {
  corekeeper: "corekeeper",
  spaceengineers: "spaceengineers",
  sandstorm: "sandstorm",
  mordhau: "mordhau",
};

/** Real mod.io game ids — see file header for how these were confirmed live. */
const GAME_ID: Record<Game, number> = {
  corekeeper: 5289,
  spaceengineers: 264,
  sandstorm: 254,
  mordhau: 169,
};

/** Server-relevant content-type filter — see file header. Only Space
 *  Engineers' taxonomy has a real non-installable majority bucket to exclude. */
const TAGS_FILTER: Partial<Record<Game, string>> = {
  spaceengineers: "Mod",
};

/** Which live tag group is "the" category facet for each game — see file header. */
const CATEGORY_GROUP: Partial<Record<Game, string>> = {
  corekeeper: "Type",
  sandstorm: "Mods",
  mordhau: "Type",
};

/** Only Core Keeper's taxonomy draws a real client/server distinction. */
const APPLICATION_TYPE_GROUP: Partial<Record<Game, string>> = {
  corekeeper: "Application Type",
};

/** Only Core Keeper's taxonomy has a real game-version group. */
const GAME_VERSION_GROUP: Partial<Record<Game, string>> = {
  corekeeper: "Game Version",
};

// ── CLI args ──────────────────────────────────────────────────────────────
function parseArgs(argv: string[]) {
  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
  const gamesArg = get("games");
  const games = (gamesArg ? gamesArg.split(",") : [...ALL_GAMES]).filter((g): g is Game =>
    (ALL_GAMES as readonly string[]).includes(g)
  );
  return {
    apply: argv.includes("--apply"),
    minDownloads: Number(get("min-downloads") ?? DEFAULT_MIN_DOWNLOADS),
    ratePerMin: Number(get("rate-per-min") ?? DEFAULT_RATE_LIMIT_PER_MIN),
    maxPages: get("max-pages") ? Number(get("max-pages")) : undefined, // smoke-test cap, not a real-run knob
    games: games.length ? games : [...ALL_GAMES],
  };
}

// ── Rate-limited, retrying fetch (same pattern as import-modrinth-catalog.ts) ──
class RateLimiter {
  private minIntervalMs: number;
  private last = 0;
  constructor(perMin: number) {
    this.minIntervalMs = 60_000 / perMin;
  }
  async wait() {
    const now = Date.now();
    const elapsed = now - this.last;
    if (elapsed < this.minIntervalMs) {
      await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
    }
    this.last = Date.now();
  }
}

async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
  await limiter.wait();
  const res = await fetch(url, { headers: { "User-Agent": UA } });
  if (res.status === 429 && attempt <= 6) {
    const retryAfterHeader = res.headers.get("retry-after");
    const retryAfterMs = retryAfterHeader ? Number(retryAfterHeader) * 1000 : 0;
    const backoffMs = Math.max(retryAfterMs, 1000 * 2 ** attempt);
    console.warn(`  [rate-limit] 429 on ${url} — backing off ${Math.round(backoffMs / 1000)}s (attempt ${attempt})`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return apiFetch(limiter, url, attempt + 1);
  }
  if (res.status >= 500 && attempt <= 4) {
    const backoffMs = 1000 * 2 ** attempt;
    console.warn(`  [server-error] ${res.status} on ${url} — retrying in ${Math.round(backoffMs / 1000)}s`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return apiFetch(limiter, url, attempt + 1);
  }
  return res;
}

// ── mod.io types (only the fields we read) ───────────────────────────────
type ModioImage = { filename: string; original: string; thumb_320x180?: string; thumb_1280x720?: string };
type ModioTag = { name: string; name_localized?: string; date_added?: number };
type ModioUser = {
  username: string;
  display_name_portal?: string | null;
  avatar?: { original?: string; thumb_100x100?: string } | null;
};
type ModioMod = {
  id: number;
  name: string;
  name_id: string;
  summary: string;
  description_plaintext?: string | null;
  profile_url: string;
  logo?: ModioImage | null;
  media?: { images?: ModioImage[] };
  tags?: ModioTag[];
  stats: { downloads_total: number; subscribers_total: number };
  submitted_by: ModioUser;
};
type ModioModsResponse = { data: ModioMod[]; result_total: number };
type ModioGame = { id: number; name: string; name_id: string; ugc_name: string };
type ModioTagGroup = { name: string; type: string; tags: string[] };
type ModioTagsResponse = { data: ModioTagGroup[] };

async function fetchGame(limiter: RateLimiter, gameId: number): Promise<ModioGame> {
  const res = await apiFetch(limiter, `${API}/games/${gameId}?api_key=${MODIO_KEY}`);
  if (!res.ok) throw new Error(`mod.io returned HTTP ${res.status} fetching game ${gameId}`);
  return (await res.json()) as ModioGame;
}

async function fetchTagGroups(limiter: RateLimiter, gameId: number): Promise<ModioTagGroup[]> {
  const res = await apiFetch(limiter, `${API}/games/${gameId}/tags?api_key=${MODIO_KEY}`);
  if (!res.ok) return [];
  const body = (await res.json()) as ModioTagsResponse;
  return body.data;
}

function galleryUrlsFrom(images: ModioImage[] | undefined): string[] {
  return (images ?? []).slice(0, GALLERY_CAP).map((img) => img.original);
}

function categoryFor(mod: ModioMod, game: Game, ugcName: string, groupValues: Set<string>): string {
  const groupName = CATEGORY_GROUP[game];
  if (groupName) {
    const hit = (mod.tags ?? []).find((t) => groupValues.has(t.name));
    if (hit) return hit.name;
  }
  return ugcName;
}

function gameVersionsFor(mod: ModioMod, game: Game, versionValues: Set<string>): string[] {
  if (!GAME_VERSION_GROUP[game]) return [];
  return (mod.tags ?? []).filter((t) => versionValues.has(t.name)).map((t) => t.name);
}

function serverSideFor(mod: ModioMod, game: Game, appTypeValues: Set<string>): string | null {
  if (!APPLICATION_TYPE_GROUP[game]) return null;
  const tagNames = new Set((mod.tags ?? []).filter((t) => appTypeValues.has(t.name)).map((t) => t.name));
  if (tagNames.has("Server")) return "required";
  if (tagNames.has("Client")) return "unsupported";
  return null;
}

type Counters = { fetched: number; belowFloor: number; eligible: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
function emptyCounters(): Counters {
  return { fetched: 0, belowFloor: 0, eligible: 0, upserted: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
}

async function importGame(opts: {
  game: Game;
  limiter: RateLimiter;
  apply: boolean;
  minDownloads: number;
  maxPages?: number;
}) {
  const { game, limiter, apply, minDownloads, maxPages } = opts;
  const gameFamily = GAME_TO_FAMILY[game];
  const gameId = GAME_ID[game];
  const counters = emptyCounters();

  console.log(`\n=== ${game} (mod.io game id ${gameId}) → gameFamily "${gameFamily}" ===`);

  const [gameInfo, tagGroups] = await Promise.all([fetchGame(limiter, gameId), fetchTagGroups(limiter, gameId)]);
  const groupTagValues = (name: string | undefined): Set<string> =>
    new Set(tagGroups.find((g) => g.name === name)?.tags ?? []);
  const categoryValues = groupTagValues(CATEGORY_GROUP[game]);
  const versionValues = groupTagValues(GAME_VERSION_GROUP[game]);
  const appTypeValues = groupTagValues(APPLICATION_TYPE_GROUP[game]);

  // Preload every existing mod_io row for this family — sourceId → existing
  // slug (never re-slugify on update), plus every slug already in use for
  // create-time collision avoidance. See file header's IDENTITY section.
  const existingRows = await db.gameMod.findMany({
    where: { gameFamily, source: "mod_io" },
    select: { id: true, slug: true, sourceId: true },
  });
  const existingBySourceId = new Map(existingRows.filter((r) => r.sourceId).map((r) => [r.sourceId as string, r]));
  const usedSlugs = new Set(existingRows.map((r) => r.slug));
  console.log(`  ${existingRows.length} existing mod_io row(s) already in this family`);

  const tagsFilter = TAGS_FILTER[game];
  let offset = 0;
  let page = 0;
  for (;;) {
    if (maxPages !== undefined && page >= maxPages) break;
    const tagsParam = tagsFilter ? `&tags=${encodeURIComponent(tagsFilter)}` : "";
    const url = `${API}/games/${gameId}/mods?api_key=${MODIO_KEY}&_limit=${PAGE_SIZE}&_offset=${offset}&_sort=-downloads_total${tagsParam}`;
    const res = await apiFetch(limiter, url);
    if (!res.ok) {
      console.error(`  [list] offset=${offset} → HTTP ${res.status}, stopping this game's pass early`);
      break;
    }
    const body = (await res.json()) as ModioModsResponse;
    page++;
    counters.fetched += body.data.length;
    if (body.data.length === 0) break;

    const eligible = body.data.filter((m) => m.stats.downloads_total > minDownloads);
    counters.belowFloor += body.data.length - eligible.length;
    counters.eligible += eligible.length;

    for (const mod of eligible) {
      if (!mod.name_id) {
        counters.skipped++;
        continue;
      }
      const category = categoryFor(mod, game, gameInfo.ugc_name, categoryValues);
      const data = {
        name: mod.name,
        category,
        description: mod.summary || null,
        longDescription: mod.description_plaintext || null,
        iconUrl: mod.logo?.thumb_320x180 ?? mod.logo?.original ?? null,
        url: mod.profile_url,
        downloads: mod.stats.downloads_total,
        license: null,
        gameVersions: gameVersionsFor(mod, game, versionValues),
        loaders: [] as string[],
        serverSide: serverSideFor(mod, game, appTypeValues),
        galleryUrls: galleryUrlsFrom(mod.media?.images),
        authorName: mod.submitted_by.display_name_portal || mod.submitted_by.username || null,
        authorAvatarUrl: mod.submitted_by.avatar?.thumb_100x100 ?? mod.submitted_by.avatar?.original ?? null,
        source: "mod_io",
        sourceId: String(mod.id),
        active: true,
        verifiedAt: new Date(),
        upstreamOk: true,
        upstreamNote: null as string | null,
      };

      if (!apply) {
        counters.upserted++;
        continue;
      }

      const existing = existingBySourceId.get(String(mod.id));
      try {
        if (existing) {
          await db.gameMod.update({ where: { id: existing.id }, data });
          counters.updated++;
        } else {
          let slug = mod.name_id;
          for (let attempt = 0; attempt < 3 && usedSlugs.has(slug); attempt++) {
            slug = attempt === 0 ? `${mod.name_id}-${mod.id}` : `${mod.name_id}-${mod.id}-${attempt}`;
          }
          usedSlugs.add(slug);
          await db.gameMod.create({ data: { gameFamily, slug, ...data } });
          counters.created++;
        }
        counters.upserted++;
      } catch (e) {
        counters.failed++;
        const msg = e instanceof Error ? e.message : String(e);
        console.error(`  [db] failed to upsert ${game}/${mod.name_id}: ${msg}`);
      }
    }

    console.log(
      `  [${game}] page=${page} offset=${offset} fetched=${body.data.length} eligible=${eligible.length} total_hits=${body.result_total} ` +
        `(running: fetched=${counters.fetched} eligible=${counters.eligible} upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} skipped=${counters.skipped} failed=${counters.failed})`
    );

    // Real early-stop: rows are sorted by -downloads_total, so once a page's
    // last (lowest-downloads) row is at or under the floor, every remaining
    // page is too — matters most for spaceengineers's 3,113-row tags=Mod pool.
    const lastRow = body.data[body.data.length - 1];
    if (lastRow && lastRow.stats.downloads_total <= minDownloads) break;

    offset += PAGE_SIZE;
    if (offset >= body.result_total) break;
  }

  return counters;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  console.log(
    `[import-modio-catalog] ${args.apply ? "APPLY (writing)" : "DRY RUN (no writes)"} — ` +
      `games: ${args.games.join(", ")}; threshold: downloads>${args.minDownloads}; ` +
      `rate: ${args.ratePerMin}/min${args.maxPages ? `; max-pages=${args.maxPages} (smoke test)` : ""}`
  );

  const limiter = new RateLimiter(args.ratePerMin);
  const totals = emptyCounters();
  const perGame: Record<string, Counters> = {};

  for (const game of args.games) {
    const counters = await importGame({ game, limiter, apply: args.apply, minDownloads: args.minDownloads, maxPages: args.maxPages });
    perGame[game] = counters;
    for (const k of Object.keys(totals) as (keyof Counters)[]) totals[k] += counters[k];
    console.log(
      `--- ${game} done: fetched=${counters.fetched} eligible=${counters.eligible} upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} skipped=${counters.skipped} failed=${counters.failed} ---`
    );
  }

  console.log(`\n============================================================`);
  console.log(`FINAL SUMMARY (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
  for (const game of args.games) {
    const c = perGame[game]!;
    console.log(
      `  ${game.padEnd(16)} fetched=${c.fetched.toString().padStart(6)} eligible=${c.eligible.toString().padStart(6)} created=${c.created.toString().padStart(6)} updated=${c.updated.toString().padStart(6)} skipped=${c.skipped} failed=${c.failed}`
    );
  }
  console.log(
    `  ${"TOTAL".padEnd(16)} fetched=${totals.fetched.toString().padStart(6)} eligible=${totals.eligible.toString().padStart(6)} created=${totals.created.toString().padStart(6)} updated=${totals.updated.toString().padStart(6)} skipped=${totals.skipped} failed=${totals.failed}`
  );
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

